#include <iostream>
#include <queue>
#include <stack>
using namespace std;

typedef struct BiTNode {
    char data;
    struct BiTNode *lchild, *rchild;
} BiTNode, *BiTree;

// 按前序扩展序列建立二叉树（'#'表示空）
void CreateBiTree(BiTree &T) {
    char ch; cin >> ch;
    if (ch == '#') T = NULL;
    else {
        T = new BiTNode;
        T->data = ch;
        CreateBiTree(T->lchild);
        CreateBiTree(T->rchild);
    }
}

// 前序遍历（递归）
void PreOrder(BiTree T) {
    if (T) { cout << T->data << " "; PreOrder(T->lchild); PreOrder(T->rchild); }
}

// 中序遍历（非递归）
void InOrder_NonRec(BiTree T) {
    stack<BiTree> S;
    BiTree p = T;
    while (p || !S.empty()) {
        if (p) { S.push(p); p = p->lchild; }
        else { p = S.top(); S.pop(); cout << p->data << " "; p = p->rchild; }
    }
}

// 层序遍历（用队列）
void LevelOrder(BiTree T) {
    queue<BiTree> Q;
    if (T) Q.push(T);
    while (!Q.empty()) {
        BiTree p = Q.front(); Q.pop();
        cout << p->data << " ";
        if (p->lchild) Q.push(p->lchild);
        if (p->rchild) Q.push(p->rchild);
    }
}

// 求二叉树的深度
int TreeDepth(BiTree T) {
    if (!T) return 0;
    int l = TreeDepth(T->lchild);
    int r = TreeDepth(T->rchild);
    return (l > r ? l : r) + 1;
}

// 求叶子结点数
int CountLeaf(BiTree T) {
    if (!T) return 0;
    if (!T->lchild && !T->rchild) return 1;
    return CountLeaf(T->lchild) + CountLeaf(T->rchild);
}

// 判断两棵二叉树是否相同
bool isSameTree(BiTree p, BiTree q) {
    if (!p && !q) return true;
    if (!p || !q) return false;
    if (p->data != q->data) return false;
    return isSameTree(p->lchild, q->lchild) && isSameTree(p->rchild, q->rchild);
}

// 示例输入: A B D # # E # # C # F # #
// 形成的树:
//       A
//      / \
//     B   C
//    / \   \
//   D   E   F
//
// 前序: A B D E C F
// 中序: D B E A C F
// 后序: D E B F C A
// 层序: A B C D E F

#include <iostream>
#include <string>
#include <cstring>
using namespace std;

typedef struct {
    int weight;         // 权值
    int parent, lchild, rchild;  // 双亲及孩子下标
} HTNode;
typedef char** HuffmanCode;  // 编码表

// 在HT[1..i-1]中选parent为0且weight最小的两个结点
void Select(HTNode* HT, int n, int &s1, int &s2) {
    int min1 = INT_MAX, min2 = INT_MAX;
    s1 = s2 = 0;
    for (int i = 1; i <= n; i++) {
        if (HT[i].parent == 0) {
            if (HT[i].weight < min1) {
                min2 = min1; s2 = s1;
                min1 = HT[i].weight; s1 = i;
            } else if (HT[i].weight < min2) {
                min2 = HT[i].weight; s2 = i;
            }
        }
    }
}

// 创建哈夫曼树并求哈夫曼编码
void HuffmanCoding(HTNode* &HT, HuffmanCode &HC, int* w, int n) {
    if (n <= 1) return;
    int m = 2 * n - 1;  // 总结点数
    HT = (HTNode*)malloc((m+1) * sizeof(HTNode));
    // 初始化叶子结点 [1..n]
    for (int i = 1; i <= n; i++) {
        HT[i].weight = w[i-1];
        HT[i].parent = HT[i].lchild = HT[i].rchild = 0;
    }
    // 初始化内部结点 [n+1..m]
    for (int i = n+1; i <= m; i++)
        HT[i].weight = HT[i].parent = HT[i].lchild = HT[i].rchild = 0;
    // 建哈夫曼树
    for (int i = n+1; i <= m; i++) {
        int s1, s2;
        Select(HT, i-1, s1, s2);
        HT[s1].parent = i; HT[s2].parent = i;
        HT[i].lchild = s1; HT[i].rchild = s2;
        HT[i].weight = HT[s1].weight + HT[s2].weight;
    }
    // 从叶子到根求每个字符的编码
    HC = (HuffmanCode)malloc((n+1) * sizeof(char*));
    char* cd = (char*)malloc(n * sizeof(char));
    cd[n-1] = '\0';
    for (int i = 1; i <= n; i++) {
        int start = n-1, c = i, f = HT[i].parent;
        while (f != 0) {  // 从叶子向上到根
            --start;
            cd[start] = (HT[f].lchild == c) ? '0' : '1';
            c = f; f = HT[f].parent;
        }
        HC[i] = (char*)malloc((n-start) * sizeof(char));
        strcpy(HC[i], &cd[start]);
    }
    free(cd);
}

// 示例：权值 [5, 3, 2, 1] 对应字符 a,b,c,d
// 哈夫曼树: 11(5,6) 6(3,3) 3(2,1)
// 编码: a=0, b=10, c=110, d=111
// WPL = 5*1 + 3*2 + 2*3 + 1*3 = 20
